{"cards": [{"node_code": "N_421fc23e367d8e4a", "definition": "研究铁路车站、编组站及枢纽内轨道布置、站场路基、站房及附属设施土建结构的设计与施工，旨在满足列车接发、编组及旅客服务需求。", "boundary": "本节点聚焦于铁路站场范围内的土建工程实体。包含站场轨道平面布置、站场路基处理、站台、雨棚、站房基础及内部结构。边界在于区分“站场土建”与“区间线路”，前者服务于节点功能，后者服务于线性运输。不包含信号通信系统、纯运输组织管理或站房内部的非土建装修细节。", "includes": ["铁路车站、编组站、枢纽的轨道平面布置与站场路基设计", "站台、雨棚、站房及站场附属设施的土建结构与施工", "站场排水、照明基础及与区间线路衔接的土建工程"], "excludes": ["铁路信号、通信、供电等机电系统的设计与安装", "纯运输组织、调度指挥及站场运营管理办法", "站房内部的精装修、家具陈设及非结构性装饰"], "sibling_distinctions": [{"other_code": "N_b2c37c0894afba29", "rule": "本节点关注“节点”（站场）内的土建布局与结构，兄弟节点“线路”关注“区间”（正线/联络线）的几何形态与路基。"}, {"other_code": "N_9830909615b38a72", "rule": "本节点包含站场内的轨道布置及站房土建，兄弟节点“轨道结构”侧重轨道部件（轨、枕、道床）的材料与构造细节，若涉及站场轨道具体构造，需结合语境，通常站场整体布局归本节点。"}], "cross_boundary_rule": "当站场轨道布置与区间线路衔接时，站界内的轨道及土建归入本节点，站界外的区间线路归入线路节点。"}, {"node_code": "N_fecf877eeebc656a", "definition": "研究铁路线路走向选择、方案比选及定线原则的学科分支，旨在根据运输需求、地形地质及经济因素确定铁路在空间中的最优路径。", "boundary": "本节点聚焦于铁路线路的宏观选线过程与决策。包含选线原则、方案拟定、比选评价及定线方法。边界在于区分“选线决策”与“具体几何设计”，前者确定大致走向与方案，后者确定具体平纵断面参数。不包含具体的路基结构设计、轨道结构细节或站场内部布局。", "includes": ["铁路选线原则、方案拟定与比选评价方法", "地形地质条件对选线的影响分析及定线技术", "铁路线路走向的空间布局与宏观规划"], "excludes": ["线路具体的平纵断面几何参数设计（如曲线半径、坡度计算）", "路基、轨道等实体结构的详细设计与施工", "铁路站场内部轨道布置及站房建筑设计"], "sibling_distinctions": [{"other_code": "N_b2c37c0894afba29", "rule": "本节点关注“选线”（宏观走向与方案决策），兄弟节点“线路”关注“线路”（具体几何形态与平纵断面设计）。"}, {"other_code": "N_455b6ee21189541c", "rule": "本节点关注线路走向的选择，兄弟节点“路基”关注支撑线路的土体基础结构。"}], "cross_boundary_rule": "当选线方案涉及具体平纵断面参数优化时，宏观走向与方案比选归入本节点，具体的几何参数计算与断面设计归入线路节点。"}]}
